describe('Record Date Display', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
    cy.login('testuser@example.com', 'password123');
  });

  it('should display created date and last modified date on a record', () => {
    cy.get('[data-testid="records-list"]').should('be.visible');
    cy.get('[data-testid="record-item"]').first().click();

    cy.get('[data-testid="record-detail"]').should('be.visible');
    cy.get('[data-testid="created-date"]').should('be.visible');
    cy.get('[data-testid="created-date"]').should('contain', new Date().getFullYear().toString());

    cy.get('[data-testid="modified-date"]').should('be.visible');
    cy.get('[data-testid="modified-date"]').should('contain', new Date().getFullYear().toString());
  });

  it('should update the last modified date when record is edited', () => {
    cy.get('[data-testid="records-list"]').should('be.visible');
    cy.get('[data-testid="record-item"]').first().click();

    cy.get('[data-testid="record-detail"]').should('be.visible');
    cy.get('[data-testid="modified-date"]').then(($element) => {
      const originalModifiedDate = $element.text();

      cy.get('[data-testid="edit-button"]').click();
      cy.get('[data-testid="record-name-input"]').clear().type('Updated Record Name');
      cy.get('[data-testid="save-button"]').click();

      cy.get('[data-testid="modified-date"]').should('not.have.text', originalModifiedDate);
      cy.get('[data-testid="modified-date"]').should('contain', new Date().getFullYear().toString());
    });
  });

  it('should display dates in correct format', () => {
    cy.get('[data-testid="records-list"]').should('be.visible');
    cy.get('[data-testid="record-item"]').first().click();

    cy.get('[data-testid="record-detail"]').should('be.visible');
    cy.get('[data-testid="created-date"]').should('match', /\d{1,2}\/\d{1,2}\/\d{4}/);
    cy.get('[data-testid="modified-date"]').should('match', /\d{1,2}\/\d{1,2}\/\d{4}/);
  });

  it('should show created date as earlier than or equal to modified date', () => {
    cy.get('[data-testid="records-list"]').should('be.visible');
    cy.get('[data-testid="record-item"]').first().click();

    cy.get('[data-testid="record-detail"]').should('be.visible');
    cy.get('[data-testid="created-date"]').invoke('text').then((createdText) => {
      cy.get('[data-testid="modified-date"]').invoke('text').then((modifiedText) => {
        const createdDate = new Date(createdText);
        const modifiedDate = new Date(modifiedText);
        expect(createdDate.getTime()).to.be.lte(modifiedDate.getTime());
      });
    });
  });
});
